diff --git a/cmd/eval-arms/sample.go b/cmd/eval-arms/sample.go
index b6d3cefb..e3d6f25c 100644
--- a/cmd/eval-arms/sample.go
+++ b/cmd/eval-arms/sample.go
@@ -249,8 +249,23 @@ func composedClaim(site, lane string, i int, kind, text string, cited, paths []s
 		refs = append(refs, site+"/"+p)
 	}
 	return investigation.Counterexample{
-		ID:             fmt.Sprintf("%s/%s/%d", site, lane, i),
-		Description:    fmt.Sprintf("[%s %s] %s", lane, kind, text),
+		ID: fmt.Sprintf("%s/%s/%d", site, lane, i),
+		// The lane is deliberately NOT in the description.
+		//
+		// The description is what evalsample renders into the blinded challenge
+		// view, and section 12 says an adjudicator should not be told which lane
+		// produced an item during first-pass labeling where the format allows it
+		// "without losing required provenance". Here it does allow it: the lane
+		// is already in the ID above, which becomes the manifest's subject_id, so
+		// hiding it in the view loses nothing and revealing it would let a
+		// usefulness rating (section 10) and a support label turn on which lane
+		// an item came from. Same shape as provider_id, which the manifest
+		// carries and the view hides.
+		//
+		// The KIND stays: it tells the adjudicator what sort of proposition they
+		// are judging, which is adjudication context rather than lane
+		// provenance, and nothing else carries it.
+		Description:    fmt.Sprintf("[%s] %s", kind, text),
 		EvidenceRefIDs: refs,
 	}
 }
diff --git a/cmd/eval-arms/sample_test.go b/cmd/eval-arms/sample_test.go
index dcff03fe..36859279 100644
--- a/cmd/eval-arms/sample_test.go
+++ b/cmd/eval-arms/sample_test.go
@@ -705,14 +705,28 @@ func TestComposedClaimsReachTheSample(t *testing.T) {
 	if len(w.Counterexamples) != 2 {
 		t.Fatalf("composed claims produced %d sampleable items, want 2", len(w.Counterexamples))
 	}
+	// The lanes must stay distinguishable for scoring (section 9 forbids
+	// treating them as one population) WITHOUT the blinded view announcing
+	// which lane an item came from (section 12). So the distinction is checked
+	// on the ID, which becomes the manifest's subject_id, and its absence is
+	// checked on the description, which is what the adjudicator reads.
 	var deterministic, model bool
 	for _, c := range w.Counterexamples {
-		if strings.Contains(c.Description, "[deterministic") {
+		if strings.Contains(c.ID, "/deterministic/") {
 			deterministic = true
 		}
-		if strings.Contains(c.Description, "[model") {
+		if strings.Contains(c.ID, "/model/") {
 			model = true
 		}
+		// Only the bracketed prefix is checked: it is the part the artifact
+		// format controls. A claim's own text may legitimately contain the word
+		// "model" (this fixture's does), and rewriting an adjudicator's claim
+		// text to avoid a substring would corrupt the thing being judged.
+		if prefix, _, ok := strings.Cut(c.Description, "] "); ok {
+			if strings.Contains(prefix, "deterministic") || strings.Contains(prefix, "model") {
+				t.Errorf("description prefix %q] names the producing lane; the blinded challenge view would tell the adjudicator which lane to trust", prefix)
+			}
+		}
 		if !strings.HasPrefix(c.ID, "one/") {
 			t.Errorf("claim %q is not attributed to its site", c.ID)
 		}
